import {trainingBag} from './bag.js';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const FLIGHT_PIXEL=2.3;
export const SHOT_FIELDS={carry:[50,330],roll:[0,40],sdSide:[0,50],sdLong:[0,40],start:[-10,10],curve:[-50,50],bias:[-35,35],height:[5,50],bigPct:[0,25],bigShift:[0,100],bigShort:[0,60],rho:[-.8,.8]};
export function defaultMemberBag(base){return trainingBag({...base,shotType:'tee',customBag:null}).map(c=>({...c,start:0,curve:0,bias:0,height:c.stock>200?32:25,bigPct:0,bigDirection:'both',bigShift:c.stock>200?40:22,bigShort:12,rho:0}));}
export function cleanMemberBag(saved,base){const defaults=defaultMemberBag(base);return defaults.map(d=>{const old=Array.isArray(saved)?saved.find(c=>c.club===d.club):null;if(!old)return d;const out={...d};for(const [key,[lo,hi]]of Object.entries(SHOT_FIELDS)){const v=key==='carry'?Number(old.stock)-Number(old.roll):Number(old[key]);out[key]=Number.isFinite(v)?clamp(v,lo,hi):(key==='carry'?d.stock-d.roll:d[key]);}out.stock=out.carry+out.roll;delete out.carry;out.bigDirection=['left','right','both'].includes(old.bigDirection)?old.bigDirection:'both';return out;});}
export function editingPattern(club){return{...club,carry:club.stock-club.roll};}
export function flightHandles(p){const start=p.carry*Math.tan(p.start*Math.PI/180);return{mid:.5*start+.25*p.curve,end:start+p.curve};}
export function moveFlightHandle(p,handle,lateral){
 const q=flightHandles(p),mid=handle==='mid'?lateral:q.mid,end=handle==='end'?lateral:q.end;
 // x(t) = S*t + C*t². Two anchors uniquely set initial direction and curve.
 const start=clamp(Math.atan2(4*mid-end,p.carry)*180/Math.PI,-10,10),s=p.carry*Math.tan(start*Math.PI/180);
 return{...p,start,curve:clamp(end-s,-50,50)};
}
export function flightDescription(p){const h=flightHandles(p),start=Math.abs(p.start)<.15?'center start':p.start>0?'push start':'pull start',curve=Math.abs(p.curve)<.5?'straight':p.curve<0?'draw':'fade';return`${start} · ${curve} · finishes ${Math.abs(h.end)<.5?'on line':Math.round(Math.abs(h.end))+' yd '+(h.end<0?'left':'right')}`;}
export function flightSVG(p){
 const point=t=>({x:300+FLIGHT_PIXEL*(p.carry*Math.tan(p.start*Math.PI/180)*t+p.curve*t*t),y:370-310*t}),path=Array.from({length:51},(_,i)=>{const q=point(i/50);return`${i?'L':'M'}${q.x.toFixed(2)},${q.y.toFixed(2)}`;}).join(' '),q=flightHandles(p);
 return`<defs><linearGradient id="editorGrass" x2="0" y2="1"><stop stop-color="#d6eac1"/><stop offset="1" stop-color="#f0f4e7"/></linearGradient></defs><rect width="600" height="410" rx="12" fill="url(#editorGrass)"/><ellipse cx="300" cy="60" rx="55" ry="25" fill="#b5d58f"/><path d="M300 370V35" stroke="#748567" stroke-dasharray="5 7"/><circle cx="300" cy="60" r="8" fill="none" stroke="#587147" stroke-width="2"/><circle cx="300" cy="60" r="3" fill="#587147"/><text x="300" y="23" text-anchor="middle" fill="#526344" font-size="12">CARRY TARGET · ${Math.round(p.carry)} YD</text><path d="${path}" fill="none" stroke="#2c6546" stroke-width="5" stroke-linecap="round"/><circle cx="300" cy="370" r="6" fill="#fffef8" stroke="#6d8161"/><path d="M300 370L${300+FLIGHT_PIXEL*p.carry*Math.tan(p.start*Math.PI/180)*.28} ${370-310*.28}" stroke="#78926c" stroke-width="2" stroke-dasharray="4 4"/><g data-handle="mid"><circle cx="${300+FLIGHT_PIXEL*q.mid}" cy="215" r="22" fill="#e9b858" stroke="#fffdf5" stroke-width="3"/><path d="M${289+FLIGHT_PIXEL*q.mid} 215h22m-18-4-4 4 4 4m14-8 4 4-4 4" fill="none" stroke="#624f2c" stroke-width="2"/></g><text x="${clamp(300+FLIGHT_PIXEL*q.mid,105,495)}" y="253" text-anchor="middle" fill="#586847" font-size="12">Drag midpoint</text><g data-handle="end"><circle cx="${300+FLIGHT_PIXEL*q.end}" cy="60" r="22" fill="#498aac" stroke="#fffdf5" stroke-width="3"/><path d="M${289+FLIGHT_PIXEL*q.end} 60h22m-18-4-4 4 4 4m14-8 4 4-4 4" fill="none" stroke="white" stroke-width="2"/></g><text x="${clamp(300+FLIGHT_PIXEL*q.end,85,515)}" y="103" text-anchor="middle" fill="#586847" font-size="12">Drag finish</text><text x="25" y="393" fill="#748366" font-size="11">LEFT / DRAW</text><text x="575" y="393" text-anchor="end" fill="#748366" font-size="11">RIGHT / FADE</text>`;
}
export function heightSVG(p){const y=166-p.height*2.4;return`<rect width="600" height="210" rx="12" fill="#edf3e8"/><path d="M40 166H560" stroke="#8da080"/><path d="M40 166Q300 ${166-p.height*4.8} 560 166" fill="none" stroke="#2c6546" stroke-width="4"/><g data-handle="height"><circle cx="300" cy="${y}" r="20" fill="#e9b858" stroke="#fffdf5" stroke-width="3"/><path d="M300 ${y-10}v20m-4-16 4-4 4 4m-8 12 4 4 4-4" fill="none" stroke="#624f2c" stroke-width="2"/></g><text x="560" y="24" text-anchor="end" fill="#526344" font-size="12">PEAK · ${Math.round(p.height)} YD</text><circle cx="40" cy="166" r="5" fill="#fffef8" stroke="#7a8e6c"/><text x="40" y="192" fill="#748366" font-size="11">SIDE VIEW · DRAG UP / DOWN</text><text x="560" y="192" text-anchor="end" fill="#748366" font-size="11">HEIGHT IS VISUAL ONLY</text>`;}
